import{_ as a}from"./chunks/mj-before.D3Lz5W5I.js";import{_ as o}from"./chunks/brief-demo-search.BnRB1lM8.js";import{_ as r,o as e,c as i,a4 as n}from"./chunks/framework.DyX1TuK3.js";const b=JSON.parse('{"title":"Michael Jackson 事件 — 一次「假滿分」的 debugging 全記錄","description":"","frontmatter":{},"headers":[],"relativePath":"mj-case.md","filePath":"mj-case.md"}'),s={name:"mj-case.md"};function l(d,t,c,g,h,m){return e(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="michael-jackson-事件-—-一次「假滿分」的-debugging-全記錄" tabindex="-1">Michael Jackson 事件 — 一次「假滿分」的 debugging 全記錄 <a class="header-anchor" href="#michael-jackson-事件-—-一次「假滿分」的-debugging-全記錄" aria-label="Permalink to &quot;Michael Jackson 事件 — 一次「假滿分」的 debugging 全記錄&quot;">​</a></h1><blockquote><p>語意搜尋 demo 站上,搜「Michael Jackson」,第一名是一部戰爭犯罪片, 分數還標著 <strong>100%</strong>。這頁記錄從現象到根因、到量測校準、到修法的完整過程。</p></blockquote><h2 id="_1-現象" tabindex="-1">1. 現象 <a class="header-anchor" href="#_1-現象" aria-label="Permalink to &quot;1. 現象&quot;">​</a></h2><img src="'+a+'" alt="修正前:Michael Jackson 查詢回傳一戰再戰並標示 100%" style="max-width:360px;border:1px solid #333;border-radius:8px;"><p><em>當時的實際畫面:第一名是戰爭犯罪片《一戰再戰》,標 100%。</em></p><ul><li>片庫 600+ 部全是電影,<strong>沒有任何 MJ 相關內容</strong>(演唱會 / 音樂紀錄片皆無)</li><li>查詢卻回了一部戰爭犯罪大片,顯示 <strong>100% 匹配</strong></li><li>卡片上的標籤(驚悚 / 犯罪 / 逃亡)跟 Michael Jackson 毫無關聯 — 使用者完全無從理解</li></ul><h2 id="_2-根因拆解" tabindex="-1">2. 根因拆解 <a class="header-anchor" href="#_2-根因拆解" aria-label="Permalink to &quot;2. 根因拆解&quot;">​</a></h2><p><strong>(a) 100% 是顯示假象。</strong> 排序內部分數是相對值 — RRF 融合分經 min-max 正規化, cross-encoder 混分也是 — 所以「這批裡的第一名」永遠被映射成 1.0。 就算整批都不相關,第一名照樣顯示 100%。</p><p><strong>(b) 為什麼是這部片?</strong> 查詢經 LLM 展開時,HyDE 會生成一段「假想劇情」—— 對 Michael Jackson 它想像出「傳奇人物的崛起與抗爭」式敘事,embedding 後拿去召回, 語意上漂向片庫裡戲劇張力最強的得獎片;此外 LLM 也展開出「美式」標籤, 讓帶有 <code>american</code> 標籤的得獎大片再吃到一次條件加分。</p><h2 id="_3-量測-先確認「有沒有真命中」量得出來" tabindex="-1">3. 量測:先確認「有沒有真命中」量得出來 <a class="header-anchor" href="#_3-量測-先確認「有沒有真命中」量得出來" aria-label="Permalink to &quot;3. 量測:先確認「有沒有真命中」量得出來&quot;">​</a></h2><p>拿使用者原句向量對片庫的最佳 cosine(<strong>不能用 HyDE 向量</strong> — 那是照著劇情寫的, 天生偏高),好查詢與壞查詢之間有清楚的 gap:</p><table tabindex="0"><thead><tr><th>查詢</th><th>top-1 cosine</th></tr></thead><tbody><tr><td>韓國犯罪驚悚片</td><td>0.626</td></tr><tr><td>母親節溫馨片</td><td>0.603</td></tr><tr><td>family adventure</td><td>0.578</td></tr><tr><td>dark comedy</td><td>0.531</td></tr><tr><td>類似寄生上流的片</td><td>0.488</td></tr><tr><td><strong>Michael Jackson</strong></td><td><strong>0.371</strong></td></tr></tbody></table><p>→ 用這個 cosine 分<strong>三段信心</strong>(門檻 0.52 / 0.45),做成熱載設定隨時可調。</p><h2 id="_4-修法-演進到三段信心帶" tabindex="-1">4. 修法(演進到三段信心帶) <a class="header-anchor" href="#_4-修法-演進到三段信心帶" aria-label="Permalink to &quot;4. 修法(演進到三段信心帶)&quot;">​</a></h2><ol><li><strong>三段信心(cosine)</strong>:用最佳原句 cosine 分 high(≥0.52)/ mid(0.45–0.52)/ low(&lt;0.45)。 low → 亮警示「片庫中沒有高度相關的結果」,仍給推測結果供編輯延伸發想。</li><li><strong>天花板帶誠實訊號</strong>:high 頂 95% / mid 頂 68% / low 頂 42% — 第一名的 % 反映 「片庫到底有沒有這片」,<strong>永遠不再出現假滿分</strong>;條件加分也推不回去。</li><li><strong>CE 不當絕對品質</strong>:後來實測 cross-encoder 對無關片照樣給高分(MJ 頂分 0.88), 所以 CE 只決定<strong>排序</strong>,信心一律錨定 cosine。</li><li><strong>對整個候選池 min-max</strong>(非顯示切片)→ 同一部片換顯示筆數,分數不變。</li><li><strong>可解釋卡片</strong>:每個結果標明「符合哪些條件」與「怎麼找到的(語意/推想/字面)」。</li></ol><blockquote><p>完整設計與校準見 <a href="/film-brain/honest">誠實匹配</a>;決策記錄見 ADR 0009。</p></blockquote><h2 id="_5-結果" tabindex="-1">5. 結果 <a class="header-anchor" href="#_5-結果" aria-label="Permalink to &quot;5. 結果&quot;">​</a></h2><p>修完後同一個查詢:歸 low 段、黃色警示出現、分數封頂 42%、 而且因為「音樂 / 舞蹈」條件加分開始正確作用,排上來的反而是音樂相關電影 — <strong>比修之前更合理</strong>。誠實機制沒有犧牲體驗,反而讓推測結果變得可用。</p><p><img src="'+o+'" alt="search demo"></p><h2 id="帶走的教訓" tabindex="-1">帶走的教訓 <a class="header-anchor" href="#帶走的教訓" aria-label="Permalink to &quot;帶走的教訓&quot;">​</a></h2><ul><li><strong>相對分數絕不能直接當絕對信心展示</strong> — min-max 後的第一名永遠是 1.0</li><li><strong>「多一層 AI 打分」不等於有了絕對品質</strong> — cross-encoder 對離題片也給高分(MJ 0.88),只能信它的排序,不能信它的數值</li><li>生成式查詢擴展(HyDE)在 out-of-domain 查詢上會「幻想出」漂移向量, 信心判斷必須錨定使用者原句</li><li>門檻不用猜 — 拿真實查詢量一次,gap 自己會說話</li><li>「誠實告訴使用者查不到」是功能,不是缺陷</li></ul>',21)])])}const k=r(s,[["render",l]]);export{b as __pageData,k as default};
